1	use comemo::{Tracked, TrackedMut};
2	use ecow::{EcoString, EcoVec, eco_format};
3	use typst_library::diag::{
4	    At, HintedStrResult, HintedString, SourceDiagnostic, SourceResult, Trace, Tracepoint,
5	    bail, error,
6	};
7	use typst_library::engine::{Engine, Sink, Traced};
8	use typst_library::foundations::{
9	    Arg, Args, Binding, Capturer, Closure, ClosureNode, Content, Context, Func,
10	    NativeElement, Scope, Scopes, SequenceElem, SymbolElem, Value,
11	};
12	use typst_library::introspection::Introspector;
13	use typst_library::math::LrElem;
14	use typst_library::{Library, World};
15	use typst_syntax::ast::{self, AstNode};
16	use typst_syntax::{Span, Spanned, SyntaxNode};
17	use typst_utils::{LazyHash, Protected};
18	
19	use crate::{
20	    Access, Eval, FlowEvent, Route, Vm, call_method_mut, hint_if_shadowed_std,
21	    is_dict_mutating_method, is_mutating_method,
22	};
23	
24	impl Eval for ast::FuncCall<'_> {
25	    type Output = Value;
26	
27	    fn eval(self, vm: &mut Vm) -> SourceResult<Self::Output> {
28	        let span = self.span();
29	        let callee = self.callee();
30	
31	        vm.engine.route.check_call_depth().at(span)?;
32	
33	        // Try to evaluate as a call to an associated function or field.
34	        if let ast::Expr::FieldAccess(access) = callee {
35	            let target_expr = access.target();
36	            let field = access.field();
37	            let (target, maybe_args) = if is_mutating_method(field.as_str()) {
38	                match maybe_resolve_mutating(vm, target_expr, field, self.args(), span)? {
39	                    Ok(value) => return Ok(value),
40	                    Err((target, args)) => (target, Some(args)),
41	                }
42	            } else {
43	                (target_expr.eval(vm)?, None)
44	            };
45	            match eval_field_callee(
46	                vm,
47	                access.to_untyped(),
48	                field.as_str(),
49	                field.span(),
50	                target,
51	                false,
52	            )? {
53	                FieldCallee::Func(func) => {
54	                    let args = match maybe_args {
55	                        Some(args) => args,
56	                        None => self.args().eval(vm)?.spanned(span),
57	                    };
58	                    call_func(vm, func, args, span)
59	                }
60	                FieldCallee::Method(func, target) => {
61	                    let mut args = match maybe_args {
62	                        Some(args) => args,
63	                        None => self.args().eval(vm)?.spanned(span),
64	                    };
65	                    // Method calls pass the target as the first argument.
66	                    args.insert(0, target_expr.span(), target);
67	                    call_func(vm, func, args, span)
68	                }
69	                FieldCallee::NonFunc(_, err) => Err(err).at(callee.span()),
70	            }
71	        } else {
72	            // Function call order: we evaluate the callee before the arguments.
73	            let func = callee
74	                .eval(vm)?
75	                .cast::<Func>()
76	                .map_err(|err| hint_if_shadowed_std(vm, &callee, err))
77	                .at(callee.span())?;
78	            let args = self.args().eval(vm)?.spanned(span);
79	            call_func(vm, func, args, span)
80	        }
81	    }
82	}
83	
84	impl Eval for ast::MathCall<'_> {
85	    type Output = Value;
86	
87	    fn eval(self, vm: &mut Vm) -> SourceResult<Self::Output> {
88	        eval_math_call(vm, self)
89	    }
90	}
91	
92	/// Evaluate a function call in math.
93	fn eval_math_call(vm: &mut Vm, math_call: ast::MathCall) -> SourceResult<Value> {
94	    let span = math_call.span();
95	    let callee = math_call.callee();
96	    let mut target_span = Span::detached();
97	
98	    vm.engine.route.check_call_depth().at(span)?;
99	
100	    let math_call_result = match callee {
101	        ast::MathAccess::MathIdent(ident) => {
102	            let callee_value = ident.eval(vm)?;
103	            // We need to call `trace_at` for the callee manually because we did
104	            // not evaluate via `ast::Expr::eval()`.
105	            vm.trace_at(ident.span(), &callee_value);
106	            match callee_value.clone().cast::<Func>() {
107	                Ok(func) => FieldCallee::Func(func),
108	                Err(err) => FieldCallee::NonFunc(callee_value, err),
109	            }
110	        }
111	        ast::MathAccess::MathFieldAccess(access) => {
112	            let target_expr = access.target();
113	            target_span = target_expr.span();
114	            let field = access.field();
115	            let target = target_expr.eval(vm)?;
116	            if is_mutating_method(field.as_str())
117	                && matches!(target, Value::Array(_) | Value::Dict(_))
118	            {
119	                // FUTURE: This is probably worth allowing once we nail down
120	                // mutable method semantics.
121	                //
122	                // Mutable methods have always produced an error in math because
123	                // `Access` was never implemented for `MathIdent`, so this
124	                // explicit error is just nicer. And while we could start to
125	                // implement `Access`, making mutable methods work in math still
126	                // requires deeper changes because math mode needs to know
127	                // whether the target is actually a function before evaluating
128	                // arguments.
129	                bail!(
130	                    span,
131	                    "cannot call mutating methods in math";
132	                    hint: "try using code mode to call the method: `#{}`",
133	                        math_call.to_untyped().full_text();
134	                );
135	            }
136	            eval_field_callee(
137	                vm,
138	                access.to_untyped(),
139	                field.as_str(),
140	                field.span(),
141	                target,
142	                true,
143	            )?
144	        }
145	    };
146	
147	    let args = math_call.args();
148	    match math_call_result {
149	        FieldCallee::Func(func) => {
150	            let args = args.eval(vm)?.spanned(span);
151	            call_func(vm, func, args, span)
152	        }
153	        FieldCallee::Method(func, target) => {
154	            let mut args = args.eval(vm)?.spanned(span);
155	            // Method calls pass the target as the first argument.
156	            args.insert(0, target_span, target);
157	            call_func(vm, func, args, span)
158	        }
159	        FieldCallee::NonFunc(callee_value, _) => {
160	            let parens = unparse_math_args(vm, args, callee)?;
161	            Ok(Value::Content(callee_value.display().spanned(callee.span()) + parens))
162	        }
163	    }
164	}
165	
166	/// Call a function.
167	fn call_func(vm: &mut Vm, func: Func, args: Args, span: Span) -> SourceResult<Value> {
168	    let func = func.spanned(span);
169	    let point = || Tracepoint::Call(func.name().map(Into::into));
170	    let f = || {
171	        func.call(&mut vm.engine, vm.context, args)
172	            .trace(vm.world(), point, span)
173	    };
174	
175	    // Stacker is broken on WASM.
176	    #[cfg(target_arch = "wasm32")]
177	    return f();
178	
179	    #[cfg(not(target_arch = "wasm32"))]
180	    stacker::maybe_grow(32 * 1024, 2 * 1024 * 1024, f)
181	}
182	
183	/// Attempt to resolve a mutating method call by evaluating args and then
184	/// attempting to access the target mutably. If the target's type doesn't
185	/// support mutating methods (only Array/Dict actually do), returns the
186	/// evaluated value and arguments.
187	///
188	/// This currently causes a number of bad errors due to limitations of the
189	/// [`Access`] trait used for mutation.
190	fn maybe_resolve_mutating(
191	    vm: &mut Vm,
192	    target: ast::Expr,
193	    field: ast::Ident,
194	    args: ast::Args,
195	    span: Span,
196	) -> SourceResult<Result<Value, (Value, Args)>> {
197	    // We evaluate the arguments first because `target_expr.access(vm)` mutably
198	    // borrows `vm`, so we won't be able to call `args.eval(vm)` afterwards.
199	    let args = args.eval(vm)?.spanned(span);
200	    match target.access(vm)? {
201	        // Skip methods that aren't actually mutating for dictionaries.
202	        target @ Value::Dict(_) if !is_dict_mutating_method(field.as_str()) => {
203	            Ok(Err((target.clone(), args)))
204	        }
205	        // Only arrays and dictionaries have mutable methods.
206	        target @ (Value::Array(_) | Value::Dict(_)) => {
207	            let value = call_method_mut(target, &field, args, span);
208	            let point = || Tracepoint::Call(Some(field.get().clone()));
209	            Ok(Ok(value.trace(vm.world(), point, span)?))
210	        }
211	        target => Ok(Err((target.clone(), args))),
212	    }
213	}
214	
215	/// The kind of callee in a field-access function call.
216	enum FieldCallee {
217	    /// A method on a type or on content, with the target value to be added as
218	    /// the first argument of the call.
219	    Method(Func, Value),
220	    /// A plain function to call.
221	    Func(Func),
222	    /// The field access doesn't actually produce a function. This will error in
223	    /// code, but not in math.
224	    NonFunc(Value, HintedString),
225	}
