980	        // Field access.
981	        test(s, "#x.y.f(z)", &["x", "z"]);
982	
983	        // Parenthesized expressions.
984	        test(s, "#f(x: 1)", &["f"]);
985	        test(s, "#(x: 1)", &[]);
986	        test(s, "#(x = 1)", &["x"]);
